(function () {
    if (typeof CESS_LIBRARY_DATA === 'undefined' || typeof findChapter !== 'function') return;
    var REPLACEMENTS = {
        'lib_histoire_5e_1': {
            1: { question: 'Quel est l’objectif principal du Congrès de Vienne (1814-1815) ?', options: ['Restaurer l’ordre ancien en Europe après la chute de Napoléon, sous la direction de Metternich', 'Organiser le partage colonial de l’Afrique entre puissances européennes', 'Mettre fin à la Première Guerre mondiale et sanctionner l’Allemagne vaincue', 'Unifier les États allemands autour de la Prusse'], correct: 0, correction: 'Après la défaite de Napoléon, les grandes puissances se réunissent au Congrès de Vienne (1814-1815) sous la direction de Metternich pour restaurer les monarchies et effacer les traces de la Révolution française et du bonapartisme.' },
            2: { question: 'Quelle relation cause → conséquence est correcte pour le Congrès de Vienne (1815) ?', options: ['La défaite de Napoléon → la réunion des grandes puissances à Vienne → le retour des dynasties légitimes (notamment les Bourbons) sur leurs trônes', 'L’assassinat de François-Ferdinand → la mobilisation générale → le déclenchement de la Première Guerre mondiale', 'La crise de 1929 → l’effondrement des banques → la montée des totalitarismes', 'Les révolutions de 1848 → le Printemps des peuples → l’unification immédiate de l’Italie et de l’Allemagne'], correct: 0, correction: 'Le principe de légitimité appliqué au Congrès de Vienne restaure les dynasties traditionnelles, notamment les Bourbons en France. Les Romanov règnent déjà en Russie : Alexandre Ier est empereur depuis 1801.' },
            3: { question: 'Que caractérise le « Printemps des peuples » de 1848 ?', options: ['Une vague révolutionnaire touchant simultanément de nombreux pays européens, mêlant revendications libérales, nationales et sociales', 'Un mouvement uniquement social limité à la France, sans dimension nationale', 'Une série de guerres entre États européens pour le contrôle des colonies', 'Un mouvement religieux visant à restaurer le pouvoir du pape en Italie'], correct: 0, correction: 'En 1848, une vague révolutionnaire balaie l’Europe en quelques semaines, mêlant libéralisme, nationalisme et revendications sociales.' },
            4: { question: 'Quelle relation cause → conséquence est correcte pour les révolutions de 1848 ?', options: ['Les tensions économiques et l’aspiration aux libertés → des soulèvements dans plusieurs capitales européennes → des échecs politiques immédiats mais un éveil durable des consciences nationales et libérales', 'Le Congrès de Vienne → la Restauration → l’indépendance immédiate de l’Italie et de l’Allemagne', 'L’assassinat de François-Ferdinand → la crise de juillet 1914 → la Première Guerre mondiale', 'La Conférence de Berlin → le partage de l’Afrique → l’indépendance du Congo en 1908'], correct: 0, correction: 'Les révolutions de 1848 échouent presque partout à court terme, mais elles font naître une conscience nationale et libérale qui portera ses fruits plus tard, notamment en Italie et en Allemagne.' },
            5: { question: 'Comment s’est réalisée l’unification italienne (1848-1870) ?', options: ['Grâce à l’alliance du mouvement national italien (Risorgimento) et de la diplomatie du royaume de Piémont-Sardaigne', 'Grâce à trois guerres menées par la Prusse sous la direction de Bismarck', 'Grâce à une décision prise lors du Congrès de Vienne en 1815', 'Grâce à une intervention directe des puissances coloniales lors de la Conférence de Berlin'], correct: 0, correction: 'L’unification italienne se réalise grâce à l’alliance du mouvement national (Risorgimento) et de la diplomatie piémontaise, dans un contexte où l’Italie était, selon Metternich, une simple « expression géographique ».' },
            6: { question: 'Quelle relation cause → conséquence est correcte pour l’unification italienne ?', options: ['L’échec des révolutions de 1848 → la persistance d’une conscience nationale italienne → l’unification de l’Italie autour du Piémont entre 1859 et 1870', 'La victoire prussienne contre la France en 1870 → la proclamation de l’Empire allemand → l’unification italienne', 'Le Congrès de Berlin de 1884-1885 → le partage colonial → l’unification italienne', 'L’assassinat de François-Ferdinand → la crise balkanique → l’unification italienne'], correct: 0, correction: 'Les révolutions de 1848 échouent en Italie, mais la conscience nationale italienne qui en est née permet l’unification progressive du pays autour du Piémont.' },
            7: { question: 'Qui est à l’origine de l’unification allemande (1864-1871) et par quelle méthode ?', options: ['Bismarck, chancelier de Prusse, qui utilise trois guerres successives et la « Realpolitik » pour unifier les États allemands autour de la Prusse', 'Metternich, chancelier d’Autriche, qui impose l’unification lors du Congrès de Vienne', 'Cavour, Premier ministre du Piémont, qui unifie l’Allemagne par la diplomatie', 'Guillaume II, empereur d’Allemagne, qui unifie le pays par la course aux armements'], correct: 0, correction: 'L’unification allemande est l’œuvre de Bismarck, qui utilise trois guerres successives et la « Realpolitik », une politique fondée sur les intérêts réels sans considérations morales.' },
            8: { question: 'Quelle relation cause → conséquence est correcte pour l’unification allemande ?', options: ['La nomination de Bismarck comme premier ministre de Prusse en 1862 → trois guerres victorieuses (dont celle contre la France en 1870-1871) → la proclamation de l’Empire allemand en 1871', 'La Conférence de Berlin de 1884-1885 → la course aux colonies → la proclamation de l’Empire allemand', 'L’assassinat de François-Ferdinand → le jeu des alliances → la proclamation de l’Empire allemand', 'La défaite italienne de 1848 → le Risorgimento → la proclamation de l’Empire allemand'], correct: 0, correction: 'Bismarck est nommé premier ministre de Prusse en 1862 par Guillaume Ier, puis mène trois guerres victorieuses qui aboutissent à la proclamation de l’Empire allemand en 1871.' },
            9: { question: 'Que désigne le terme « impérialisme » tel que présenté dans le chapitre ?', options: ['La domination politique, économique et culturelle exercée par les puissances industrielles européennes sur d’autres peuples et territoires, notamment en Afrique et en Asie', 'Le partage de l’Europe entre les vainqueurs de la Première Guerre mondiale', 'L’alliance militaire entre puissances européennes rivales avant 1914', 'Le retour des dynasties légitimes sur leurs trônes après 1815'], correct: 0, correction: 'L’impérialisme désigne la domination politique, économique et culturelle des puissances industrielles européennes sur l’Afrique et l’Asie ; entre 1870 et 1914, les Européens s’emparent de 80 % de la surface du globe.' },
            10: { question: 'Quelle relation cause → conséquence est correcte pour les causes de l’impérialisme ?', options: ['La recherche de matières premières et de débouchés commerciaux par les puissances industrielles → la conquête de territoires en Afrique et en Asie → la domination de 80 % du globe par les Européens en 1914', 'Les rivalités entre la Triple Alliance et la Triple Entente → la crise de juillet 1914 → la Première Guerre mondiale', 'La crise économique de 1929 → l’appauvrissement des classes moyennes → la montée des totalitarismes', 'La défaite de Napoléon → le Congrès de Vienne → la Restauration des monarchies'], correct: 0, correction: 'Les causes économiques (matières premières, débouchés, placements de capitaux) expliquent en grande partie la conquête coloniale qui mène les Européens à dominer 80 % du globe vers 1914.' },
            11: { question: 'Qu’établit la Conférence de Berlin (1884-1885) ?', options: ['Les règles du partage colonial de l’Afrique entre puissances européennes, sans consultation des populations africaines, dont le principe d’occupation effective', 'L’indépendance des colonies africaines vis-à-vis des puissances européennes', 'La création de la Société des Nations pour maintenir la paix', 'Le partage des colonies allemandes après la Première Guerre mondiale'], correct: 0, correction: 'La Conférence de Berlin réunit 14 puissances européennes qui fixent les règles du partage de l’Afrique, notamment le principe d’occupation effective, sans consulter les Africains.' },
            12: { question: 'Quelle relation cause → conséquence est correcte pour le partage de l’Afrique ?', options: ['Les rivalités coloniales entre puissances européennes → la Conférence de Berlin de 1884-1885 fixant les règles du partage → l’Afrique passe de 10 % à 90 % sous contrôle européen entre 1880 et 1914', 'La révolte des Boxers en Chine → l’intervention de huit puissances → la fin du colonialisme européen en Asie', 'Le scandale du Congo → les campagnes de dénonciation internationales → l’annexion du Congo par la Belgique en 1908', 'La victoire éthiopienne d’Adoua en 1896 → le recul des puissances coloniales → l’indépendance de toutes les colonies africaines dès 1900'], correct: 0, correction: 'La Conférence de Berlin règle la compétition coloniale entre puissances européennes ; conséquence directe, l’Afrique passe de 10 % à 90 % sous contrôle européen entre 1880 et 1914.' },
            13: { question: 'Pourquoi le Congo est-il un cas emblématique de la colonisation ?', options: ['Parce que Léopold II, roi des Belges, l’a possédé personnellement de 1885 à 1908 et y a instauré un régime de terreur devenu symbole des abus coloniaux', 'Parce que le Congo a été la première colonie africaine à obtenir son indépendance, dès 1908', 'Parce que la Conférence de Berlin s’y est tenue en 1884-1885', 'Parce que le Congo a résisté militairement à toute tentative de colonisation, comme l’Éthiopie'], correct: 0, correction: 'Léopold II obtient le Congo à Berlin comme propriété personnelle (1885-1908) et y instaure un régime de terreur (travail forcé, mutilations) devenu le symbole des abus coloniaux.' },
            14: { question: 'Quelle relation cause → conséquence est correcte pour le Congo belge ?', options: ['La demande mondiale de caoutchouc et le pouvoir sans contrôle de Léopold II → l’exploitation forcée de la population congolaise → un scandale international qui pousse la Belgique à annexer le Congo en 1908', 'La Conférence de Berlin de 1884-1885 → l’indépendance immédiate du Congo → la fin de la présence belge en Afrique', 'La victoire d’Adoua en 1896 → la reconnaissance de l’indépendance éthiopienne → l’annexion du Congo par l’Italie', 'L’assassinat de Patrice Lumumba en 1961 → la crise congolaise → l’annexion du Congo par la Belgique en 1908'], correct: 0, correction: 'La demande mondiale de caoutchouc et l’absence de contrôle sur le pouvoir de Léopold II mènent à une exploitation forcée dénoncée par des campagnes internationales, ce qui aboutit à l’annexion du Congo par la Belgique en 1908.' },
            15: { question: 'Quel exemple illustre une résistance anticoloniale ayant réussi à préserver l’indépendance d’un pays africain ?', options: ['La victoire éthiopienne d’Adoua en 1896, qui permet à l’Éthiopie de rester le seul pays africain indépendant', 'La révolte des Boxers en Chine, qui aboutit à l’indépendance totale du pays en 1901', 'La résistance de Samory Touré, qui empêche définitivement la colonisation française en Afrique de l’Ouest', 'La révolte des Herero en Namibie, qui contraint l’Allemagne à quitter la colonie dès 1904'], correct: 0, correction: 'En écrasant l’armée italienne à Adoua en 1896, l’Éthiopie reste le seul pays africain à conserver son indépendance durant la période coloniale.' },
            16: { question: 'Quelle relation cause → conséquence est correcte pour les résistances anticoloniales ?', options: ['La domination coloniale et ses violences → des résistances variées des peuples colonisés → des résultats contrastés, de la victoire éthiopienne d’Adoua au génocide herero en Namibie', 'La victoire d’Adoua en 1896 → la colonisation totale de l’Afrique → la Conférence de Berlin en 1884-1885', 'Le satyagraha de Gandhi dès 1915 → l’indépendance immédiate de l’Inde → la partition de l’Inde en 1920', 'La révolte des Herero → la victoire des Herero sur l’armée allemande → l’indépendance de la Namibie en 1908'], correct: 0, correction: 'Face à la domination coloniale, les résistances prennent des formes variées (guerre, résistance passive) avec des résultats très différents : victoire d’Adoua, mais aussi le génocide herero commis par l’armée allemande en Namibie (1904-1908).' },
            17: { question: 'Que caractérise un régime totalitaire ?', options: ['Un régime qui cherche à contrôler tous les aspects de la vie des citoyens (politique, économique, social, culturel, privé) et s’oppose au libéralisme démocratique', 'Un régime qui limite son contrôle aux seules décisions politiques et laisse une entière liberté économique', 'Un régime monarchique fondé sur le principe de légitimité dynastique', 'Un régime qui organise des élections libres avec plusieurs partis en concurrence'], correct: 0, correction: 'Un régime totalitaire cherche à contrôler tous les aspects de la vie des citoyens et s’oppose au libéralisme démocratique et à l’État de droit.' },
            18: { question: 'Quelle relation cause → conséquence est correcte pour définir un régime totalitaire ?', options: ['L’instauration d’un parti unique légal, toute opposition étant interdite → la concentration du pouvoir entre les mains d’un chef ou d’un parti → l’utilisation de la terreur et de la propagande pour contrôler la société', 'La signature du traité de Versailles en 1919 → l’humiliation allemande → l’instauration immédiate d’un régime totalitaire en France', 'La Conférence de Berlin en 1884-1885 → le partage colonial → l’instauration de régimes totalitaires en Afrique', 'Le Congrès de Vienne en 1815 → la Restauration → l’instauration de régimes totalitaires en Europe'], correct: 0, correction: 'Dans un régime totalitaire, le parti unique interdit toute opposition, ce qui permet la concentration du pouvoir et l’usage systématique de la terreur et de la propagande.' },
            19: { question: 'Que s’est-il passé en Russie entre 1917 et la formation de l’URSS ?', options: ['La guerre a aggravé les pénuries et discrédité le tsarisme ; la révolution de Février a renversé Nicolas II, puis les bolcheviks ont pris le pouvoir en octobre 1917, suivis d’une guerre civile', 'Le tsar Nicolas II a mené la Russie à la victoire, ce qui a renforcé la monarchie jusqu’en 1945', 'Staline a pris le pouvoir dès 1917 en renversant directement le tsar Nicolas II', 'La Russie s’est retirée de la Première Guerre mondiale après la victoire des armées blanches sur les bolcheviks'], correct: 0, correction: 'La guerre discrédite le tsarisme ; la révolution de Février 1917 renverse Nicolas II, puis les bolcheviks prennent le pouvoir en octobre 1917, avant que la guerre civile et le communisme de guerre ne transforment le pays.' },
            20: { question: 'Quelle relation cause → conséquence est correcte pour la naissance de l’URSS ?', options: ['Les pénuries et le discrédit du tsarisme dus à la guerre → la révolution de Février 1917 renversant Nicolas II → la prise du pouvoir par les bolcheviks en octobre 1917 puis la guerre civile', 'L’assassinat de François-Ferdinand en 1914 → la révolution bolchevique → la chute du tsar en 1917', 'La crise de 1929 → l’effondrement économique → la révolution bolchevique de 1917', 'Le traité de Versailles de 1919 → l’humiliation russe → la révolution bolchevique de 1917'], correct: 0, correction: 'C’est l’aggravation des pénuries et le discrédit du tsarisme dus à la guerre qui provoquent la révolution de Février 1917, puis la prise du pouvoir bolchevique en octobre de la même année.' },
            21: { question: 'Qu’est-ce qui caractérise le nouvel ordre international mis en place après 1945 ?', options: ['La création de l’ONU (Charte signée en juin 1945, Conseil de sécurité avec cinq membres permanents dotés d’un droit de veto) et la tenue des procès de Nuremberg jugeant les dirigeants nazis', 'La création de la Société des Nations, seule organisation chargée de maintenir la paix mondiale', 'La signature du traité de Versailles imposant des réparations à l’Allemagne', 'La tenue de la Conférence de Berlin organisant le partage colonial du monde'], correct: 0, correction: 'La Charte des Nations unies est signée en juin 1945, le Conseil de sécurité associe cinq membres permanents avec droit de veto, et les procès de Nuremberg (1945-1946) jugent les dirigeants nazis.' },
            22: { question: 'Quelle relation cause → conséquence est correcte pour la naissance de l’ONU et du nouvel ordre international ?', options: ['L’échec de la SDN et l’ampleur des crimes de la Seconde Guerre mondiale → la création d’institutions internationales (ONU, tribunal de Nuremberg) → de nouvelles normes internationales, limitées par les rapports de puissance', 'La victoire d’Adoua en 1896 → l’affaiblissement européen → la création de l’ONU en 1945', 'Le traité de Versailles en 1919 → la clause de culpabilité de guerre → la création de l’ONU en 1919', 'La révolution bolchevique de 1917 → la guerre civile russe → la création de l’ONU dès 1918'], correct: 0, correction: 'L’échec de la SDN à empêcher la Seconde Guerre mondiale et l’ampleur de ses crimes mènent à la création de l’ONU et du tribunal de Nuremberg, instaurant de nouvelles normes internationales encore limitées par les rapports de puissance.' }
        },
        'lib_histoire_5e_2': {
            1: { question: 'Quelles sont les causes de la Première Guerre mondiale évoquées dans le chapitre ?', options: ['Des causes profondes accumulées (rivalités impérialistes, nationalismes, course aux armements, système d’alliances, tensions balkaniques) et un élément déclencheur, l’assassinat de François-Ferdinand en 1914', 'Uniquement l’invasion de la Pologne par l’Allemagne en septembre 1939', 'La crise économique de 1929 qui a ruiné les grandes puissances européennes', 'Le seul refus allemand de payer les réparations imposées par le traité de Versailles'], correct: 0, correction: 'La guerre résulte de causes profondes (rivalités impérialistes, nationalismes, course aux armements, alliances, question des Balkans) et d’un élément déclencheur, l’assassinat de François-Ferdinand à Sarajevo le 28 juin 1914.' },
            2: { question: 'Quelle relation cause → conséquence est correcte pour les causes de la guerre ?', options: ['L’assassinat de l’archiduc François-Ferdinand à Sarajevo le 28 juin 1914 → l’ultimatum autrichien à la Serbie et le jeu des alliances → le basculement de l’Europe dans la guerre en quelques semaines', 'Le traité de Versailles de 1919 → l’humiliation allemande → l’assassinat de François-Ferdinand en 1914', 'L’invasion de la Belgique en 1940 → l’entrée en guerre du Royaume-Uni → la Première Guerre mondiale', 'La crise de 1929 → la montée du chômage → l’assassinat de François-Ferdinand'], correct: 0, correction: 'L’assassinat de François-Ferdinand entraîne un ultimatum autrichien à la Serbie ; par le jeu des alliances, l’Europe bascule en guerre en moins de six semaines (juillet-août 1914).' },
            3: { question: 'Comment débute le conflit sur le plan militaire en 1914 ?', options: ['L’Allemagne applique le plan Schlieffen, une attaque rapide passant par la Belgique neutre, avant que le front ne se stabilise en guerre de tranchées après la bataille de la Marne', 'Les Alliés lancent immédiatement un débarquement en Normandie pour libérer la France', 'La guerre commence par l’entrée en guerre directe des États-Unis aux côtés de la France', 'L’Allemagne attaque directement la Russie sans passer par la Belgique ni la France'], correct: 0, correction: 'L’Allemagne applique le plan Schlieffen en attaquant par la Belgique neutre ; le « miracle de la Marne » stoppe cette avancée et le front se stabilise en guerre de tranchées.' },
            4: { question: 'Quelle relation cause → conséquence est correcte pour le déroulement de la guerre ?', options: ['L’échec du plan Schlieffen lors de la bataille de la Marne (septembre 1914) → la stabilisation du front occidental → l’installation d’une guerre de tranchées et d’usure jusqu’en 1918', 'La révolution russe de février 1917 → l’entrée en guerre des États-Unis → la fin immédiate de la guerre', 'La bataille de Verdun en 1916 → la victoire allemande décisive → la fin du front occidental', 'L’armistice du 11 novembre 1918 → la bataille de la Somme → l’entrée en guerre de la Russie'], correct: 0, correction: 'Le miracle de la Marne (septembre 1914) met fin à la guerre de mouvement allemande et stabilise le front occidental dans une longue guerre de tranchées et d’usure.' },
            5: { question: 'Que caractérise la vie quotidienne des soldats dans les tranchées ?', options: ['Des conditions inhumaines (boue, rats, poux) dans des fossés, séparées par un « no man’s land » meurtrier, avec l’apparition d’armes nouvelles comme les gaz de combat et les chars', 'Des conditions de vie confortables grâce à un armistice tacite entre soldats adverses', 'Une guerre de mouvement rapide sans stabilisation du front pendant tout le conflit', 'L’absence totale de nouvelles armes, la guerre se déroulant comme au XIXe siècle'], correct: 0, correction: 'Les tranchées sont des fossés insalubres (boue, rats, poux), séparées de l’ennemi par un « no man’s land » criblé d’obus, et de nouvelles armes (gaz, chars) apparaissent dès 1915-1916.' },
            6: { question: 'Quelle relation cause → conséquence est correcte pour la guerre des tranchées ?', options: ['L’usage massif de l’artillerie et des mitrailleuses → l’enlisement dans une guerre de position meurtrière → l’apparition de traumatismes psychologiques et des mutineries, comme celles de 1917 dans l’armée française', 'L’entrée en guerre des États-Unis en 1917 → la fin des tranchées → le retour à une guerre de mouvement immédiate', 'Le traité de Versailles de 1919 → la démobilisation des troupes → les mutineries de 1917', 'La révolution russe de 1917 → la paix de Brest-Litovsk → les mutineries dans l’armée allemande'], correct: 0, correction: 'L’artillerie et les mitrailleuses rendent les assauts extrêmement meurtriers, ce qui enlise le conflit et provoque traumatismes (« obus ») et mutineries, notamment dans l’armée française en 1917.' },
            7: { question: 'Quel est l’ordre de grandeur du bilan humain de la Première Guerre mondiale ?', options: ['Environ 9 à 10 millions de morts militaires et 6 à 7 millions de morts civils, auxquels s’ajoutent 20 millions de blessés et une grippe espagnole particulièrement meurtrière', 'Environ 60 millions de morts au total, principalement des victimes civiles de bombardements aériens', 'Moins d’un million de morts, la guerre restant limitée au front occidental', 'Environ 6 millions de morts, tous des victimes de la Shoah'], correct: 0, correction: 'La Première Guerre mondiale fait 9 à 10 millions de morts militaires, 6 à 7 millions de morts civils, 20 millions de blessés, et la grippe espagnole (1918-1919) tue 50 à 100 millions de personnes dans le monde.' },
            8: { question: 'Quelle relation cause → conséquence est correcte pour le bilan de la guerre ?', options: ['Quatre années de guerre industrielle et de guerre d’usure → un nombre inédit de morts et de blessés → une Europe exsangue, avec des destructions économiques immenses en France et en Belgique', 'La crise de 1929 → le chômage de masse → le bilan humain de la Première Guerre mondiale', 'Le traité de Versailles → les réparations allemandes → la grippe espagnole de 1918-1919', 'L’armistice du 11 novembre 1918 → la démobilisation → l’augmentation du nombre de morts après la guerre'], correct: 0, correction: 'La durée et l’intensité industrielle de la guerre expliquent l’ampleur inédite des pertes humaines et des destructions économiques, en particulier dans le nord de la France et en Belgique.' },
            9: { question: 'Que prévoit le traité de Versailles (28 juin 1919) à l’égard de l’Allemagne ?', options: ['Il impose à l’Allemagne la responsabilité de la guerre (article 231), des réparations financières énormes, des pertes territoriales et une armée limitée, sans qu’elle ait participé aux négociations', 'Il accorde à l’Allemagne de nouvelles colonies en échange de son soutien à la SDN', 'Il partage l’Allemagne en deux États occupés par les Alliés jusqu’en 1990', 'Il annule toutes les dettes de guerre entre les puissances européennes'], correct: 0, correction: 'Le traité de Versailles, rédigé sans l’Allemagne, impose l’article 231 (culpabilité de guerre), des réparations de 132 milliards de marks-or, des pertes territoriales et une armée limitée à 100 000 hommes.' },
            10: { question: 'Quelle relation cause → conséquence est correcte pour le traité de Versailles ?', options: ['Des conditions de paix jugées humiliantes par les Allemands (le « Diktat ») → un ressentiment nationaliste combiné à la crise économique des années 1920-1930 → un terrain favorable à la montée d’Hitler et du nazisme', 'La victoire de l’Allemagne en 1918 → la clause de culpabilité de guerre → la création de la SDN par les États-Unis', 'L’assassinat de François-Ferdinand en 1914 → le traité de Versailles → la Seconde Guerre mondiale immédiate en 1919', 'La crise de 1929 → le traité de Versailles → la montée du nazisme en 1933'], correct: 0, correction: 'Les Allemands ressentent le traité comme un « Diktat » humiliant ; combiné à la crise économique, ce ressentiment nourrit le nationalisme qui permettra la montée d’Hitler.' },
            11: { question: 'Comment se caractérise l’occupation allemande de la Belgique durant la Première Guerre mondiale ?', options: ['L’administration allemande contrôle la majeure partie du territoire, impose réquisitions et pénuries, déporte des travailleurs en 1916, tandis que résistances et activisme flamand coexistent', 'La Belgique reste totalement libre et neutre pendant toute la guerre, sans occupation', 'L’armée belge occupe l’ensemble du territoire allemand dès 1914', 'La Belgique est intégrée à l’Empire allemand comme province à part entière dès 1914'], correct: 0, correction: 'L’administration allemande contrôle la majeure partie de la Belgique occupée, impose réquisitions, pénuries et déportations de travailleurs (1916), avec des comportements divers face à l’occupant (résistance, activisme flamand).' },
            12: { question: 'Quelle relation cause → conséquence est correcte pour l’occupation allemande de la Belgique ?', options: ['L’invasion allemande de 1914 et les besoins militaires de l’occupant → le contrôle, l’exploitation économique et la déportation de travailleurs belges → une crise sociale durable et des mémoires concurrentes après la guerre', 'Le traité de Versailles de 1919 → l’occupation allemande de la Belgique → la déportation des travailleurs en 1916', 'La bataille de la Marne en 1914 → la libération immédiate de la Belgique → la fin de l’occupation dès 1914', 'La révolution russe de 1917 → l’occupation allemande de la Belgique → l’activisme flamand'], correct: 0, correction: 'L’invasion de 1914 et les besoins militaires allemands mènent à une exploitation prolongée de la Belgique occupée (réquisitions, déportations de travailleurs en 1916), avec des conséquences sociales durables.' },
            13: { question: 'Parmi ces événements liés au début de la Première Guerre mondiale, lequel s’est produit en premier ?', options: ['Les crises marocaines (1905 et 1911), liées aux rivalités impérialistes', 'L’assassinat de l’archiduc François-Ferdinand à Sarajevo (28 juin 1914)', 'L’ultimatum de l’Autriche-Hongrie à la Serbie (juillet 1914)', 'L’entrée en guerre officielle de l’Autriche-Hongrie contre la Serbie (28 juillet 1914)'], correct: 0, correction: 'Les crises marocaines de 1905 et 1911 illustrent les rivalités impérialistes bien avant l’assassinat de Sarajevo (juin 1914), l’ultimatum (juillet 1914) et la déclaration de guerre (28 juillet 1914).' }
        },
        'lib_histoire_5e_3': {
            1: { question: 'Comment Mussolini arrive-t-il au pouvoir en Italie ?', options: ['Après la Marche sur Rome en octobre 1922, le roi Victor-Emmanuel III le nomme Premier ministre ; il instaure ensuite une dictature fasciste', 'Il est élu démocratiquement chef du gouvernement lors d’élections libres en 1919', 'Il prend le pouvoir par un coup d’État militaire contre le roi en 1929', 'Il est nommé chancelier par le président Hindenburg en 1933'], correct: 0, correction: 'Après la Marche sur Rome (octobre 1922), le roi Victor-Emmanuel III nomme Mussolini Premier ministre ; celui-ci instaure progressivement une dictature (dissolution des partis, police secrète OVRA).' },
            2: { question: 'Quelle relation cause → conséquence est correcte pour le fascisme italien ?', options: ['La déception d’après-guerre et les peurs sociales en Italie → la Marche sur Rome (1922) et la nomination de Mussolini → l’instauration progressive d’une dictature (lois fascistissimes de 1925-1926)', 'La crise de 1929 → l’effondrement des banques italiennes → la nomination de Mussolini en 1922', 'L’invasion de l’Éthiopie par l’Italie → les sanctions de la SDN → la nomination de Mussolini comme Premier ministre', 'L’incendie du Reichstag en 1933 → la suspension des libertés → la Marche sur Rome'], correct: 0, correction: 'La déception d’après-guerre et les peurs sociales alimentent les Faisceaux de Mussolini ; la Marche sur Rome (1922) mène à sa nomination, puis aux lois fascistissimes de 1925-1926 qui instaurent la dictature.' },
            3: { question: 'Quand et comment Hitler arrive-t-il au pouvoir en Allemagne ?', options: ['Le 30 janvier 1933, il est nommé chancelier par le président Hindenburg, puis instaure une dictature raciste et expansionniste (NSDAP)', 'Il est élu directement président de l’Allemagne par référendum populaire en 1933', 'Il prend le pouvoir par un coup d’État militaire après l’incendie du Reichstag', 'Il succède à Guillaume II à la tête de l’Empire allemand en 1918'], correct: 0, correction: 'Hitler est nommé chancelier par le président Hindenburg le 30 janvier 1933, avant d’instaurer une dictature raciste et expansionniste à la tête du parti nazi (NSDAP).' },
            4: { question: 'Quelle relation cause → conséquence est correcte pour le nazisme allemand ?', options: ['La fragilité politique de la République de Weimar et la mobilisation nazie → la nomination d’Hitler comme chancelier (1933) puis l’élimination des oppositions → l’instauration d’une dictature raciale préparant la guerre', 'La Grande Terreur stalinienne de 1936-1938 → les purges → la nomination d’Hitler comme chancelier en 1933', 'Les accords du Latran de 1929 → la réconciliation avec le Vatican → la nomination d’Hitler comme chancelier', 'L’invasion de la Pologne en 1939 → la Seconde Guerre mondiale → la nomination d’Hitler comme chancelier en 1933'], correct: 0, correction: 'La fragilité de la République de Weimar permet la nomination d’Hitler en 1933 ; l’incendie du Reichstag et l’élimination des oppositions installent ensuite une dictature raciale qui prépare la guerre.' },
            5: { question: 'Comment Staline exerce-t-il le pouvoir en URSS ?', options: ['Il instaure une dictature terroriste après la mort de Lénine (1924), marquée par la collectivisation forcée, les plans quinquennaux, la Grande Terreur (1936-1938) et un culte de la personnalité', 'Il partage le pouvoir démocratiquement avec plusieurs partis au sein d’un régime pluraliste', 'Il abolit la propriété collective pour développer une économie de marché libérale', 'Il se contente d’un rôle honorifique, le pouvoir réel restant entre les mains du Parti communiste sans chef unique'], correct: 0, correction: 'Staline prend le contrôle de l’URSS après la mort de Lénine (1924) et instaure une dictature terroriste : collectivisation forcée, plans quinquennaux, Grande Terreur et culte de la personnalité.' },
            6: { question: 'Quelle relation cause → conséquence est correcte pour le stalinisme en URSS ?', options: ['La volonté de transformer rapidement l’économie soviétique → la collectivisation forcée des terres et les plans quinquennaux → une famine dévastatrice en Ukraine (Holodomor) et une industrialisation rapide de l’URSS', 'La mort de Staline en 1953 → la collectivisation forcée → l’Holodomor en Ukraine', 'Les accords du Latran de 1929 → la réconciliation avec l’Église orthodoxe → la collectivisation forcée en URSS', 'L’invasion allemande de l’URSS en 1941 → la collectivisation forcée des terres → l’Holodomor en Ukraine'], correct: 0, correction: 'La volonté de transformer rapidement l’économie soviétique mène à la collectivisation forcée (1929-1933), qui provoque l’Holodomor en Ukraine, tout en permettant une industrialisation rapide via les plans quinquennaux.' },
            7: { question: 'Que désigne la « crise de 1929 » et quel a été son rôle dans l’entre-deux-guerres ?', options: ['Le krach boursier de Wall Street qui provoque une grave crise économique mondiale, favorisant le chômage de masse et la montée des mouvements totalitaires en Europe', 'Le krach financier qui a directement provoqué le déclenchement de la Première Guerre mondiale en 1914', 'La famine provoquée par la collectivisation forcée des terres en Ukraine soviétique', 'Le nom donné à la crise politique italienne ayant permis la Marche sur Rome en 1922'], correct: 0, correction: 'La crise de 1929, née du krach boursier de Wall Street, provoque une crise économique mondiale qui fragilise les démocraties et favorise la montée des régimes totalitaires en Europe.' },
            8: { question: 'Que désigne le « fascisme » tel que fondé par Mussolini en Italie ?', options: ['Une idéologie nationaliste, anti-libérale et anti-communiste, exaltant la violence, la hiérarchie et la nation, mise en place par Mussolini à partir de 1922', 'Une idéologie internationaliste prônant l’union des travailleurs de tous les pays contre le capitalisme', 'Un régime démocratique parlementaire fondé sur le multipartisme et la liberté de la presse', 'Une idéologie exclusivement religieuse visant à instaurer un État théocratique en Europe'], correct: 0, correction: 'Le fascisme, fondé par Mussolini, est une idéologie nationaliste, anti-libérale et anti-communiste qui exalte la violence, la hiérarchie et la nation.' },
            9: { question: 'Que désigne le « nazisme » du parti d’Hitler ?', options: ['Une idéologie raciste, antisémite et nationaliste extrême, fondée sur le mythe de la « race aryenne » supérieure et la conquête d’un « espace vital » à l’Est', 'Une idéologie communiste internationaliste visant l’égalité entre tous les peuples', 'Une doctrine libérale prônant le multipartisme et la limitation du pouvoir de l’État', 'Une idéologie pacifiste rejetant toute forme d’expansion territoriale'], correct: 0, correction: 'Le nazisme est une idéologie raciste et antisémite fondée sur la supériorité prétendue de la « race aryenne » et la conquête d’un « espace vital » (Lebensraum) à l’Est.' },
            10: { question: 'Parmi ces événements du fascisme italien, lequel s’est produit en premier ?', options: ['La fondation des Faisceaux italiens de combat par Mussolini à Milan (1919)', 'La Marche sur Rome et la nomination de Mussolini comme Premier ministre (octobre 1922)', 'Les accords du Latran avec le Vatican (1929)', 'L’invasion de l’Éthiopie par l’Italie (1935-1936)'], correct: 0, correction: 'Mussolini fonde les Faisceaux italiens de combat à Milan dès 1919, avant la Marche sur Rome (1922), les accords du Latran (1929) et l’invasion de l’Éthiopie (1935-1936).' },
            11: { question: 'Pour analyser un discours de propagande de Mussolini comme source historique, que faut-il prioritairement prendre en compte ?', options: ['Que c’est un document produit par le régime lui-même, destiné à convaincre et à légitimer le pouvoir : il faut le croiser avec d’autres sources pour vérifier les faits qu’il avance', 'Le considérer comme un compte-rendu neutre et objectif des faits, puisqu’il émane d’un chef d’État', 'L’ignorer totalement, car un discours politique ne peut jamais servir de source historique', 'Le comparer uniquement à d’autres discours de Mussolini, sans le confronter aux connaissances établies par les historiens'], correct: 0, correction: 'Un discours de propagande est un document engagé, produit par le pouvoir pour convaincre : un historien doit identifier son auteur et son intention, puis le croiser avec d’autres sources.' },
            12: { question: 'Parmi ces événements du nazisme allemand, lequel s’est produit en premier ?', options: ['L’incendie du Reichstag (février 1933)', 'Les lois de Nuremberg privant les Juifs de la citoyenneté allemande (1935)', 'La Nuit de Cristal, pogrom contre les Juifs (novembre 1938)', 'L’invasion de la Pologne, début de la Seconde Guerre mondiale (septembre 1939)'], correct: 0, correction: 'L’incendie du Reichstag (février 1933) précède les lois de Nuremberg (1935), la Nuit de Cristal (1938) et l’invasion de la Pologne (1939).' },
            13: { question: 'Que faut-il vérifier en priorité pour évaluer la fiabilité d’une affiche de propagande nazie comme source historique ?', options: ['Sa nature (document de propagande), son auteur (le régime nazi), son intention (convaincre et endoctriner) et donc ses limites, un point de vue situé qui doit être confronté aux faits établis', 'Uniquement la qualité artistique de l’affiche, qui garantit à elle seule sa fiabilité historique', 'Le fait qu’elle ait été produite après 1945, ce qui la rend automatiquement neutre', 'Le nombre d’exemplaires imprimés, seul critère permettant de juger de sa véracité'], correct: 0, correction: 'Une affiche de propagande doit être analysée selon sa nature, son auteur et son intention : c’est un point de vue situé, qui doit être confronté aux connaissances établies avant d’être utilisé comme preuve.' }
        },
        'lib_histoire_5e_4': {
            1: { question: 'Que caractérise la Seconde industrialisation et la Belle Époque ?', options: ['Le développement de l’électricité, de la chimie, de l’acier et du moteur à combustion, l’essor des grandes entreprises et de nouveaux biens de consommation urbains, dans une prospérité inégalement répartie', 'La disparition complète de l’industrie au profit d’une économie exclusivement agricole', 'Une période de paix totale sans aucune tension entre puissances européennes', 'Une répartition parfaitement égalitaire des richesses entre toutes les classes sociales'], correct: 0, correction: 'La Seconde industrialisation développe électricité, chimie, acier et moteur à combustion, avec de grandes entreprises et de nouveaux biens urbains, mais la prospérité reste très inégalement répartie.' },
            2: { question: 'Quelle relation cause → conséquence est correcte pour la Seconde industrialisation et la Belle Époque ?', options: ['Les innovations techniques (électricité, chimie, moteur à combustion) → l’essor de grandes entreprises et de nouveaux biens de consommation → une prospérité urbaine réelle mais très inégalement répartie entre les classes sociales', 'Le traité de Versailles de 1919 → les réparations allemandes → la Seconde industrialisation', 'La crise de 1929 → le chômage de masse → la Seconde industrialisation et la Belle Époque', 'L’assassinat de François-Ferdinand en 1914 → la Première Guerre mondiale → la Seconde industrialisation'], correct: 0, correction: 'Les innovations techniques permettent l’essor de grandes entreprises et de nouveaux biens de consommation, mais cette prospérité de la Belle Époque profite très inégalement aux différentes classes sociales.' },
            3: { question: 'Que désigne l’expression « guerre d’anéantissement » durant la Seconde Guerre mondiale ?', options: ['Une guerre qui ne vise pas seulement la victoire militaire mais la destruction totale de l’adversaire et de populations entières, comme sur le front de l’Est et dans la Shoah', 'Une guerre limitée aux seules forces armées, épargnant systématiquement les populations civiles', 'Un accord entre belligérants pour limiter les destructions matérielles', 'Une stratégie militaire consistant à négocier rapidement un armistice sans combats'], correct: 0, correction: 'La guerre d’anéantissement vise la destruction totale de l’adversaire, y compris des populations civiles entières, comme le montrent le front de l’Est et la Shoah.' },
            4: { question: 'Que désigne l’« occupation » d’un territoire durant la Seconde Guerre mondiale, comme en Belgique ?', options: ['Le contrôle d’un pays vaincu par l’armée et l’administration de la puissance occupante, qui impose réquisitions, pénuries et travail obligatoire à la population', 'Un régime d’alliance librement consentie entre deux États souverains', 'Une aide économique apportée par un pays vainqueur à un pays vaincu', 'Une période de gouvernement provisoire choisi par élection libre dans le pays vaincu'], correct: 0, correction: 'L’occupation désigne le contrôle d’un territoire vaincu par l’armée et l’administration ennemies, qui imposent réquisitions, pénuries et travail obligatoire, comme en Belgique de 1940 à 1944.' },
            5: { question: 'Que désignent les termes « résistance » et « collaboration » durant l’occupation ?', options: ['Deux attitudes opposées face à l’occupant : la résistance lutte clandestinement contre lui, tandis que la collaboration coopère avec lui (comme Rex ou le VNV en Belgique)', 'Deux formes différentes d’administration militaire allemande sans lien avec la population locale', 'Deux partis politiques belges créés après la Libération de 1944', 'Deux étapes successives et non contradictoires de la même politique d’occupation'], correct: 0, correction: 'La résistance lutte clandestinement contre l’occupant (sabotage, renseignement, aide aux persécutés), tandis que la collaboration coopère avec lui, comme Rex (Degrelle) ou le VNV en Belgique.' },
            6: { question: 'Que désigne la « Shoah » ?', options: ['L’extermination systématique et délibérée d’environ six millions de Juifs d’Europe par le régime nazi entre 1941 et 1945', 'La déportation de prisonniers politiques soviétiques vers les goulags de Sibérie', 'Le nom donné aux procès de Nuremberg jugeant les criminels de guerre nazis', 'La persécution des populations civiles pendant la Première Guerre mondiale'], correct: 0, correction: 'La Shoah est l’extermination systématique et délibérée d’environ six millions de Juifs d’Europe par le régime nazi entre 1941 et 1945, le génocide le plus documenté de l’histoire.' },
            7: { question: 'Que désigne la « libération » à la fin de la Seconde Guerre mondiale, par exemple en Belgique ?', options: ['La reconquête des territoires occupés par les forces alliées, comme la libération de Bruxelles le 4 septembre 1944', 'La signature du traité de Versailles en 1919 mettant fin à l’occupation allemande', 'La proclamation de l’indépendance des colonies belges d’Afrique', 'Le retrait volontaire de l’armée allemande sans intervention alliée'], correct: 0, correction: 'La libération désigne la reconquête des territoires occupés par les forces alliées ; Bruxelles est ainsi libérée le 4 septembre 1944.' },
            8: { question: 'Quelle chaîne cause → transformation → conséquence décrit correctement la Shoah ?', options: ['L’antisémitisme racial nazi combiné à la guerre de conquête → la radicalisation progressive vers l’extermination (ghettos, Einsatzgruppen, camps) après la conférence de Wannsee (1942) → la destruction des communautés juives d’Europe', 'Les lois de Nuremberg de 1935 → la Nuit de Cristal → la libération d’Auschwitz par les Alliés occidentaux en 1943', 'La conférence de Wannsee en 1942 → l’entrée en guerre des États-Unis → l’invasion de la Pologne en 1939', 'La libération d’Auschwitz en 1945 → la conférence de Wannsee → les lois de Nuremberg de 1935'], correct: 0, correction: 'L’antisémitisme nazi et la guerre de conquête mènent à une radicalisation progressive (ghettos, Einsatzgruppen, puis camps d’extermination après la conférence de Wannsee en 1942), aboutissant à la destruction des communautés juives d’Europe.' },
            9: { question: 'Quelle chaîne cause → transformation → conséquence décrit correctement la Belgique pendant la Seconde Guerre mondiale ?', options: ['La défaite belge de mai 1940 et l’occupation qui suit → des choix divers (collaboration, résistance, attentisme) face à l’occupant → une répression sévère et une épuration marquée par des divisions après la Libération', 'La libération de Bruxelles en 1944 → la capitulation belge de 1940 → l’occupation allemande de la Belgique', 'L’abdication de Léopold III en 1951 → l’invasion allemande de mai 1940 → la Question royale', 'Le traité de Versailles de 1919 → l’invasion allemande de la Belgique en 1940 → la Libération de 1944'], correct: 0, correction: 'La défaite de mai 1940 entraîne une occupation durant laquelle Belges collaborent, résistent ou s’accommodent ; la Libération de 1944 est suivie d’une épuration marquée par des divisions, jusqu’à la Question royale de 1951.' },
            10: { question: 'Parmi ces étapes de la Shoah, laquelle s’est produite en premier ?', options: ['Les lois de Nuremberg et l’exclusion progressive des Juifs de la vie publique (1935)', 'La conférence de Wannsee planifiant la « Solution finale » (janvier 1942)', 'La déportation des Juifs de Hongrie (1944)', 'La libération d’Auschwitz par l’Armée rouge (janvier 1945)'], correct: 0, correction: 'Les lois de Nuremberg de 1935 précèdent la conférence de Wannsee (1942), la déportation des Juifs de Hongrie (1944) et la libération d’Auschwitz (janvier 1945).' },
            11: { question: 'Pour évaluer un témoignage de rescapé de la Shoah comme source historique, que faut-il garder à l’esprit ?', options: ['Qu’il constitue un témoignage précieux et unique, mais qu’il reflète une expérience individuelle et une mémoire parfois affectée par le temps, à croiser avec d’autres sources', 'Qu’il doit être rejeté systématiquement car aucun témoignage oral n’a de valeur historique', 'Qu’il est forcément plus fiable que tout document d’archive administratif nazi', 'Qu’il représente automatiquement l’expérience de l’ensemble des victimes de la Shoah sans nuance'], correct: 0, correction: 'Un témoignage de rescapé est une source précieuse mais reflète une expérience individuelle, à croiser avec des archives et d’autres témoignages pour construire une connaissance historique fiable.' },
            12: { question: 'Parmi ces événements liés à la Belgique durant la Seconde Guerre mondiale, lequel s’est produit en premier ?', options: ['L’invasion allemande et la capitulation du roi Léopold III (mai 1940)', 'La libération de Bruxelles par les troupes alliées (4 septembre 1944)', 'L’abdication de Léopold III à la suite de la Question royale (1951)', 'La déportation de la majorité des 25 000 Juifs de Belgique (1942-1944)'], correct: 0, correction: 'L’invasion et la capitulation belge de mai 1940 précèdent les déportations de 1942-1944, la libération de Bruxelles (1944) et l’abdication de Léopold III (1951).' },
            13: { question: 'Que faut-il examiner en priorité pour évaluer la fiabilité d’un tract de la résistance belge comme source historique ?', options: ['Sa nature clandestine et son intention de mobiliser contre l’occupant, ce qui en fait un point de vue engagé à confronter à d’autres sources pour établir les faits', 'Le fait qu’il ait été imprimé, ce qui garantit automatiquement son objectivité totale', 'Sa date de publication après la guerre, qui le rendrait plus fiable qu’un document contemporain', 'Le nombre de pages du tract, seul critère pertinent pour juger de sa valeur historique'], correct: 0, correction: 'Un tract de résistance est un document engagé, produit clandestinement pour mobiliser contre l’occupant : il faut identifier son intention et le croiser avec d’autres sources avant de l’utiliser comme preuve.' }
        },
        'lib_histoire_5e_5': {
            1: { question: 'Que désigne l’ONU et quel est son rôle dans le contexte de l’après-guerre ?', options: ['L’Organisation des Nations unies, créée en 1945 pour maintenir la paix internationale, dotée d’un Conseil de sécurité avec cinq membres permanents disposant d’un droit de veto', 'L’alliance militaire occidentale créée en 1949 pour contrer l’URSS', 'L’organisation créée en 1919 pour maintenir la paix, ancêtre de l’ONU', 'L’alliance militaire des pays communistes créée en 1955 en réponse à l’OTAN'], correct: 0, correction: 'L’ONU est créée en 1945 (Charte signée en juin) pour maintenir la paix internationale ; son Conseil de sécurité associe cinq membres permanents dotés d’un droit de veto.' },
            2: { question: 'Que désigne la « guerre froide » ?', options: ['Le conflit idéologique, politique et militaire opposant les États-Unis et l’URSS de 1947 à 1991, sans affrontement armé direct entre les deux superpuissances', 'Un conflit armé direct entre les États-Unis et l’URSS ayant fait des millions de morts', 'L’alliance militaire entre les États-Unis et l’URSS contre l’Allemagne nazie', 'La guerre opposant la France et l’Allemagne pour le contrôle de l’Alsace-Lorraine'], correct: 0, correction: 'La guerre froide désigne le conflit idéologique, politique et militaire entre les États-Unis et l’URSS, de 1947 à la chute de l’URSS en 1991, sans affrontement armé direct entre les deux superpuissances.' },
            3: { question: 'Que désignent l’OTAN et le pacte de Varsovie ?', options: ['Les deux alliances militaires opposées de la guerre froide, l’OTAN (1949) regroupant les pays occidentaux et le pacte de Varsovie (1955) les pays communistes', 'Deux traités de paix signés à la fin de la Première Guerre mondiale', 'Deux organisations économiques créées pour gérer le Plan Marshall en Europe', 'Deux accords limitant les armements nucléaires signés dans les années 1970'], correct: 0, correction: 'L’OTAN (1949) et le pacte de Varsovie (1955) sont les deux alliances militaires rivales qui structurent les blocs occidental et communiste pendant la guerre froide.' },
            4: { question: 'Que désignent les « crises » de la guerre froide comme celle de Cuba (1962) ?', options: ['Des épisodes de très forte tension entre les blocs, parfois proches d’un affrontement direct, comme la crise des missiles de Cuba en octobre 1962', 'Des périodes de coopération économique renforcée entre les États-Unis et l’URSS', 'Des conflits armés directs entre les armées américaine et soviétique en Europe', 'Des négociations ayant abouti à la dissolution immédiate de l’OTAN'], correct: 0, correction: 'Les crises de la guerre froide, comme celle des missiles de Cuba en octobre 1962, sont des épisodes de très forte tension entre les blocs, sans toutefois déboucher sur un affrontement armé direct.' },
            5: { question: 'Que désigne la « dissuasion nucléaire » durant la guerre froide ?', options: ['La stratégie consistant à posséder un armement nucléaire suffisant pour décourager l’adversaire d’attaquer, chaque camp craignant une riposte destructrice', 'L’interdiction totale de toute arme nucléaire décidée par l’ONU dès 1945', 'L’usage effectif de l’arme nucléaire par les États-Unis et l’URSS l’un contre l’autre', 'Une alliance militaire entre les États-Unis et l’URSS pour partager leurs armes nucléaires'], correct: 0, correction: 'La dissuasion nucléaire consiste à posséder un arsenal suffisant pour décourager toute attaque de l’adversaire, par crainte d’une riposte destructrice ; elle explique l’absence de guerre directe entre les deux superpuissances.' },
            6: { question: 'Quelle chaîne cause → transformation → conséquence décrit correctement la naissance de la Guerre froide ?', options: ['L’opposition idéologique et stratégique entre les États-Unis et l’URSS après 1945 → la formation d’alliances rivales (OTAN, pacte de Varsovie) et le blocus de Berlin (1948-1949) → la bipolarisation du monde en deux blocs antagonistes', 'La chute du mur de Berlin en 1989 → la formation de l’OTAN en 1949 → la bipolarisation du monde', 'La crise des missiles de Cuba en 1962 → le blocus de Berlin en 1948 → la naissance de la Guerre froide', 'La dissolution de l’URSS en 1991 → l’opposition idéologique entre blocs → la formation de l’OTAN'], correct: 0, correction: 'L’opposition idéologique entre les États-Unis et l’URSS après 1945 mène à la formation de blocs rivaux et au blocus de Berlin (1948-1949), fixant une bipolarisation durable du monde.' },
            7: { question: 'Quelle chaîne cause → transformation → conséquence décrit correctement une grande crise de la Guerre froide ?', options: ['La découverte de missiles soviétiques à Cuba en 1962 → treize jours de tension extrême entre Kennedy et Khrouchtchev → le retrait des missiles et le développement de mécanismes de dialogue entre superpuissances', 'L’invasion de l’Afghanistan par l’URSS en 1979 → la crise des missiles de Cuba → la chute du mur de Berlin en 1989', 'La chute du mur de Berlin en 1989 → la guerre de Corée → la crise des missiles de Cuba', 'Le lancement de Spoutnik en 1957 → la guerre du Vietnam → la crise des missiles de Cuba'], correct: 0, correction: 'La découverte de missiles soviétiques à Cuba en octobre 1962 provoque treize jours de tension extrême ; la crise se résout par le retrait des missiles et favorise ensuite le dialogue entre superpuissances.' },
            8: { question: 'Quelle chaîne cause → transformation → conséquence décrit correctement la naissance de l’ONU et du nouvel ordre international ?', options: ['L’échec de la SDN et l’ampleur des crimes de la Seconde Guerre mondiale → la création de l’ONU et la tenue des procès de Nuremberg → l’adoption de nouvelles normes internationales comme la Déclaration universelle des droits de l’homme (1948)', 'La crise des missiles de Cuba en 1962 → la tension nucléaire → la création de l’ONU en 1945', 'Le blocus de Berlin en 1948 → la formation des blocs → la création de l’ONU en 1945', 'La chute du mur de Berlin en 1989 → la fin de la guerre froide → la création de l’ONU'], correct: 0, correction: 'L’échec de la SDN et l’ampleur des crimes de la Seconde Guerre mondiale mènent à la création de l’ONU et à la tenue des procès de Nuremberg, puis à l’adoption de la Déclaration universelle des droits de l’homme en 1948.' },
            9: { question: 'Quelle comparaison entre les États-Unis et l’URSS pendant la guerre froide est correcte ?', options: ['Les États-Unis défendent le capitalisme et le multipartisme, tandis que l’URSS impose une économie planifiée et un parti unique (le PCUS)', 'Les deux superpuissances partagent la même idéologie mais s’opposent uniquement sur des questions territoriales', 'Les États-Unis imposent un parti unique alors que l’URSS pratique des élections pluralistes', 'Les deux superpuissances pratiquent une économie planifiée identique mais avec des drapeaux différents'], correct: 0, correction: 'Les États-Unis reposent sur le capitalisme, la démocratie libérale et le multipartisme, tandis que l’URSS impose une économie planifiée, un parti unique (le PCUS) et la censure.' },
            10: { question: 'Parmi ces événements de la naissance de la Guerre froide, lequel s’est produit en premier ?', options: ['La doctrine Truman et le Plan Marshall (1947)', 'Le blocus de Berlin (1948-1949)', 'La création de l’OTAN (1949)', 'La création du pacte de Varsovie (1955)'], correct: 0, correction: 'La doctrine Truman et le Plan Marshall datent de 1947, avant le blocus de Berlin (1948-1949), la création de l’OTAN (1949) et celle du pacte de Varsovie (1955).' },
            11: { question: 'Que faut-il examiner en priorité pour évaluer la fiabilité d’un discours officiel américain ou soviétique sur les débuts de la guerre froide ?', options: ['Son auteur et son camp d’origine, son intention de propagande, afin de le confronter à d’autres sources avant de l’utiliser comme preuve historique', 'Sa seule longueur, un discours long étant automatiquement plus fiable qu’un discours court', 'Le fait qu’il ait été prononcé en public, ce qui garantirait à lui seul son objectivité', 'La date de sa traduction en français, seul critère pertinent pour juger sa valeur'], correct: 0, correction: 'Un discours officiel émane d’un camp engagé dans la guerre froide : il faut identifier son auteur et son intention de propagande avant de le confronter à d’autres sources.' },
            12: { question: 'Parmi ces grandes crises de la Guerre froide, laquelle s’est produite en premier ?', options: ['La guerre de Corée (1950-1953)', 'La construction du mur de Berlin (1961)', 'La crise des missiles de Cuba (1962)', 'L’invasion de l’Afghanistan par l’URSS (1979)'], correct: 0, correction: 'La guerre de Corée (1950-1953) précède la construction du mur de Berlin (1961), la crise de Cuba (1962) et l’invasion de l’Afghanistan (1979).' },
            13: { question: 'Que faut-il garder à l’esprit pour évaluer une photographie de propagande diffusée pendant une crise de la guerre froide (comme celle de Cuba) ?', options: ['Qu’elle a pu être sélectionnée ou mise en scène pour servir les intérêts d’un camp, et qu’il faut donc la croiser avec d’autres sources pour vérifier les faits qu’elle prétend montrer', 'Qu’une photographie constitue toujours une preuve neutre et incontestable des faits', 'Qu’elle ne peut jamais être utilisée par un historien, quelle que soit la manière dont elle est analysée', 'Que sa qualité technique suffit à elle seule à garantir son exactitude historique'], correct: 0, correction: 'Une photographie de propagande peut être choisie ou mise en scène pour servir un camp : un historien doit la confronter à d’autres sources avant de l’utiliser comme preuve.' }
        },
        'lib_histoire_5e_6': {
            1: { question: 'Comment débute la révolution belge de 1830 ?', options: ['Après une représentation de l’opéra « La Muette de Portici » à Bruxelles en août 1830, le public sort dans la rue et déclenche une insurrection contre l’union avec les Pays-Bas', 'Par un vote du Congrès de Vienne accordant l’indépendance à la Belgique en 1815', 'Par une invasion militaire française destinée à annexer la Belgique en 1830', 'Par une grève générale ouvrière réclamant de meilleures conditions de travail'], correct: 0, correction: 'En août 1830, une représentation de l’opéra « La Muette de Portici » à Bruxelles pousse le public dans la rue, déclenchant l’insurrection contre l’union avec les Pays-Bas.' },
            2: { question: 'Quelle relation cause → conséquence est correcte pour la révolution belge de 1830 ?', options: ['Le mécontentement face à quinze ans d’union forcée avec les Pays-Bas, encouragé par la révolution française de juillet 1830 → l’insurrection de Bruxelles en août 1830 → l’indépendance de la Belgique', 'Le Congrès de Vienne de 1815 → la révolution française de juillet 1830 → l’indépendance immédiate de la Belgique dès 1815', 'La Conférence de Berlin de 1884-1885 → le partage colonial → la révolution belge de 1830', 'L’indépendance du Congo en 1960 → la crise congolaise → la révolution belge de 1830'], correct: 0, correction: 'Après quinze ans d’union forcée avec les Pays-Bas, et encouragés par la révolution française de juillet 1830, les Belges se soulèvent en août 1830, ce qui mène à l’indépendance de la Belgique.' },
            3: { question: 'Que représente l’indépendance de l’Inde dans le processus de décolonisation ?', options: ['Une indépendance négociée avec le Royaume-Uni en 1947, portée notamment par Gandhi, mais accompagnée d’une partition sanglante entre l’Inde et le Pakistan', 'Une indépendance obtenue par une guerre coloniale contre la France, achevée en 1954', 'Une indépendance obtenue sans aucune négociation ni tension, dès la fin du XIXe siècle', 'Une colonie ayant conservé un statut colonial jusque dans les années 1970'], correct: 0, correction: 'L’Inde obtient en 1947 une indépendance négociée avec le Royaume-Uni, portée par Gandhi, mais marquée par une partition sanglante entre l’Inde et le Pakistan (environ un million de morts).' },
            4: { question: 'Que caractérise la décolonisation de l’Afrique subsaharienne (1956-1965) ?', options: ['Une vague d’indépendances souvent obtenues pacifiquement pour les anciennes colonies françaises et britanniques, dans un mouvement de nationalisme anticolonial porté par la Seconde Guerre mondiale', 'Un processus exclusivement violent, chaque pays ayant dû mener une guerre d’indépendance contre son ancienne métropole', 'Un mouvement qui n’a concerné que les colonies portugaises comme l’Angola et le Mozambique', 'Une décolonisation achevée dès le Congrès de Vienne de 1815'], correct: 0, correction: 'Entre 1956 et 1965, une vague d’indépendances souvent pacifiques touche les anciennes colonies françaises et britanniques d’Afrique subsaharienne, portée par les nationalismes renforcés par la Seconde Guerre mondiale.' },
            5: { question: 'Comment se caractérise l’indépendance du Congo belge en 1960 ?', options: ['Une indépendance précipitée, proclamée le 30 juin 1960, suivie d’une grave crise politique et de l’assassinat de Patrice Lumumba en 1961', 'Une indépendance négociée pendant plus de vingt ans, obtenue sans aucune crise politique', 'Une indépendance obtenue après une longue guerre coloniale comparable à celle d’Algérie', 'Une indépendance proclamée en 1908, en même temps que l’annexion du Congo par la Belgique'], correct: 0, correction: 'Le Congo belge obtient une indépendance précipitée le 30 juin 1960, suivie d’une grave crise politique (crise du Congo) et de l’assassinat de Patrice Lumumba en 1961.' },
            6: { question: 'Quel rôle jouent les mouvements nationalistes dans la décolonisation après 1945 ?', options: ['Renforcés par l’affaiblissement des empires coloniaux durant la Seconde Guerre mondiale, ils réclament et obtiennent l’indépendance de leurs pays entre 1945 et 1975', 'Ils cherchent à renforcer les liens coloniaux avec les métropoles européennes plutôt qu’à obtenir l’indépendance', 'Ils apparaissent uniquement après 1975, une fois toutes les colonies déjà indépendantes', 'Ils sont créés et dirigés directement par les gouvernements coloniaux européens'], correct: 0, correction: 'La Seconde Guerre mondiale affaiblit les empires coloniaux et renforce les mouvements nationalistes, qui obtiennent l’indépendance de la plupart des colonies entre 1945 et 1975.' },
            7: { question: 'Que désignent les « héritages coloniaux » dans les nouveaux États issus de la décolonisation ?', options: ['Les frontières héritées de la colonisation, les structures économiques et administratives mises en place par les puissances européennes, qui pèsent sur la construction des nouveaux États', 'L’absence totale de toute trace de la colonisation dans les nouveaux États indépendants', 'Le remboursement volontaire par les nouveaux États des dettes contractées par les colonisateurs', 'Un système politique démocratique stable directement transmis par les anciennes puissances coloniales'], correct: 0, correction: 'Les héritages coloniaux désignent les frontières et les structures économiques et administratives héritées de la colonisation, qui pèsent durablement sur la construction des États nouvellement indépendants.' },
            8: { question: 'Quelle chaîne cause → transformation → conséquence décrit correctement la décolonisation (1945-1975) ?', options: ['L’affaiblissement des empires coloniaux pendant la Seconde Guerre mondiale et la montée des nationalismes → des négociations ou des guerres d’indépendance (Inde 1947, Indochine 1954, Algérie 1962, Congo 1960) → la naissance de nouveaux États confrontés à des défis postcoloniaux', 'La Conférence de Berlin de 1884-1885 → le partage colonial de l’Afrique → la décolonisation immédiate des colonies dès 1885', 'L’indépendance du Congo en 1960 → la Seconde Guerre mondiale → l’affaiblissement des empires coloniaux', 'La révolution des Œillets au Portugal en 1974 → la Seconde Guerre mondiale → l’indépendance de l’Inde en 1947'], correct: 0, correction: 'L’affaiblissement des empires coloniaux pendant la Seconde Guerre mondiale et la montée des nationalismes mènent à des indépendances négociées ou obtenues par la guerre (Inde 1947, Indochine 1954, Congo 1960, Algérie 1962), suivies de défis postcoloniaux.' },
            9: { question: 'Quelle comparaison entre la décolonisation de l’Inde et celle du Congo belge est correcte ?', options: ['L’Inde obtient son indépendance en 1947 après une négociation portée par Gandhi, tandis que le Congo belge obtient une indépendance précipitée en 1960 suivie d’une grave crise politique', 'Les deux pays obtiennent leur indépendance la même année, en 1947, dans des conditions identiques', 'Le Congo belge obtient son indépendance avant l’Inde, dès 1908, sans aucune crise politique', 'L’Inde et le Congo belge restent tous deux sous domination coloniale jusqu’en 1975'], correct: 0, correction: 'L’Inde obtient son indépendance en 1947 par la négociation, portée par Gandhi, alors que le Congo belge obtient en 1960 une indépendance précipitée suivie d’une grave crise politique.' },
            10: { question: 'Parmi ces indépendances, laquelle a eu lieu en premier ?', options: ['L’indépendance de l’Inde et du Pakistan (1947)', 'L’indépendance de l’Indochine (Vietnam), après les accords de Genève (1954)', 'L’indépendance du Congo belge (1960)', 'L’indépendance de l’Algérie, après les accords d’Évian (1962)'], correct: 0, correction: 'L’indépendance de l’Inde et du Pakistan (1947) précède celle de l’Indochine (1954), du Congo belge (1960) et de l’Algérie (1962).' },
            11: { question: 'Que faut-il examiner en priorité pour évaluer la fiabilité d’un discours d’un dirigeant nationaliste (comme Lumumba) sur l’indépendance de son pays ?', options: ['Sa nature (un discours politique engagé), l’intention de son auteur (mobiliser et légitimer la lutte pour l’indépendance) et donc la nécessité de le croiser avec d’autres sources', 'Le considérer comme un compte-rendu totalement neutre des événements, dépourvu de tout point de vue', 'Le rejeter automatiquement comme source, un discours politique n’ayant selon les historiens aucune valeur', 'Ne retenir que la date du discours, sans tenir compte de son auteur ni de son contexte'], correct: 0, correction: 'Un discours de dirigeant nationaliste est un document engagé, destiné à mobiliser et à légitimer la lutte pour l’indépendance : il doit être croisé avec d’autres sources avant d’être utilisé comme preuve.' },
            12: { question: 'Quelle affirmation correspond à un fait établi sur les décolonisations entre 1945 et 1975 ?', options: ['La plupart des colonies africaines et asiatiques obtiennent leur indépendance entre 1945 et 1975, selon des modalités très différentes (négociation, guerre, indépendance précipitée)', 'Toutes les colonies obtiennent leur indépendance exactement à la même date, en 1960', 'Les décolonisations se sont toutes déroulées de manière pacifique, sans aucune guerre ni crise', 'Les décolonisations ont commencé après 1989, avec la chute du mur de Berlin'], correct: 0, correction: 'Entre 1945 et 1975, la plupart des colonies africaines et asiatiques obtiennent leur indépendance, mais selon des modalités très différentes : négociation (Inde), guerre (Algérie, Indochine) ou indépendance précipitée (Congo).' },
            13: { question: 'Quelle affirmation correspond à un fait établi sur les conséquences des décolonisations ?', options: ['Les nouveaux États indépendants doivent construire leur unité nationale et leur développement dans des frontières souvent héritées de la colonisation, ce qui explique en partie des tensions postcoloniales', 'Les nouveaux États indépendants ont immédiatement effacé toute trace de frontières coloniales', 'Les décolonisations ont mis fin à toute relation économique entre anciennes colonies et anciennes métropoles', 'Les nouveaux États indépendants ont tous adopté un régime politique identique dès leur indépendance'], correct: 0, correction: 'Les nouveaux États doivent construire leur unité et leur développement dans des frontières souvent héritées de la colonisation, ce qui explique en partie les tensions et crises postcoloniales observées après les indépendances.' }
        }
    };
    Object.keys(REPLACEMENTS).forEach(function (id) {
        var chapter = findChapter(id);
        if (!chapter) return;
        var repl = REPLACEMENTS[id];
        Object.keys(repl).forEach(function (idxStr) {
            var i = Number(idxStr);
            var ex = chapter.exercices[i];
            if (!ex) return;
            var r = repl[idxStr];
            ex.question = r.question;
            ex.options = r.options;
            ex.correct = r.correct;
            ex.correction = r.correction;
            ex.contentVersion = (ex.contentVersion || 0) + 1;
        });
    });
})();

